"""Regression coverage for preparation of Maybe deciders."""

import pytest

import factory


@pytest.mark.parametrize('chance, expected', [(0, 'no'), (100, 'yes')])
@pytest.mark.parametrize('locale', [None, 'en_US', 'fr_FR'])
def test_faker_decider_defaults(chance, expected, locale):
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker(
                'pybool',
                locale=locale,
                truth_probability=factory.LazyFunction(lambda: chance),
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory.create_batch(3) == [{'result': expected}] * 3


@pytest.mark.parametrize('choice', [True, False])
def test_nested_maybe_decider(choice):
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Maybe(
                factory.LazyFunction(lambda: choice),
                yes_declaration=True,
                no_declaration=False,
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['result'] == ('yes' if choice else 'no')


def test_branch_overrides_are_not_decider_overrides():
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker('pybool', truth_probability=100),
            yes_declaration=factory.Faker('pyint'),
            no_declaration=None,
        )

    assert ExampleFactory(result__min_value=42, result__max_value=42)['result'] == 42
